package io.tornado.reporting;import io.tornado.datafetch.BinanceMarketDataClient;import io.tornado.notification.*;import io.tornado.persistence.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import org.springframework.test.util.ReflectionTestUtils;import java.math.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class MixTradeSimulationServiceTest{@Test void qualifyingConsensusCreatesOneSimulationAndPersistsTelegramMessageId(){Fixture f=new Fixture();when(f.simulations.existsByActiveKey(anyString())).thenReturn(false);when(f.simulations.saveAndFlush(any())).thenAnswer(i->{MixTradeSimulation s=i.getArgument(0);ReflectionTestUtils.setField(s,"id",99L);return s;});when(f.telegram.send(anyString())).thenReturn(new TelegramNotificationService.DeliveryResult(TelegramNotificationService.DeliveryResult.Status.SENT,42L,null));f.service.detect(f.coin,f.predictions(),Instant.EPOCH,new BigDecimal("100"));ArgumentCaptor<MixTradeSimulation>capture=ArgumentCaptor.forClass(MixTradeSimulation.class);verify(f.simulations).saveAndFlush(capture.capture());assertThat(capture.getValue().getTelegramMessageId()).isEqualTo(42);verify(f.telegram).send(contains("🚨 TORNIDO SIGNAL"));}
 @Test void duplicateActiveKeySuppressesSimulationAndNotification(){Fixture f=new Fixture();when(f.simulations.existsByActiveKey(anyString())).thenReturn(true);f.service.detect(f.coin,f.predictions(),Instant.EPOCH,new BigDecimal("100"));verify(f.simulations,never()).saveAndFlush(any());verifyNoInteractions(f.telegram);}
 @Test void targetClosureEditsOriginalTelegramMessage(){Fixture f=new Fixture();MixTradeSimulation simulation=f.simulation(Direction.UP);when(f.simulations.lockOpenByPair("BTCUSDT")).thenReturn(List.of(simulation));when(f.telegram.edit(eq(42L),anyString())).thenReturn(new TelegramNotificationService.DeliveryResult(TelegramNotificationService.DeliveryResult.Status.SENT,42L,null));f.service.observe("BTCUSDT",simulation.getTargetPrice(),Instant.EPOCH.plusSeconds(60));verify(f.telegram).edit(eq(42L),contains("TARGET HIT"));verify(f.telegram,never()).send(anyString());}
 @Test void stopClosureAttemptsEditAndFallsBackToNewMessageOnEditFailure(){Fixture f=new Fixture();MixTradeSimulation simulation=f.simulation(Direction.DOWN);when(f.simulations.lockOpenByPair("BTCUSDT")).thenReturn(List.of(simulation));when(f.telegram.edit(eq(42L),anyString())).thenReturn(new TelegramNotificationService.DeliveryResult(TelegramNotificationService.DeliveryResult.Status.FAILED,null,"edit failed"));f.service.observe("BTCUSDT",simulation.getStopLossPrice(),Instant.EPOCH.plusSeconds(60));verify(f.telegram).edit(eq(42L),contains("STOP LOSS HIT"));verify(f.telegram).send(contains("STOP LOSS HIT"));}
 @Test void recoveryUsesFirstHistoricalBoundaryTouch(){Fixture f=new Fixture();MixTradeSimulation simulation=f.simulation(Direction.UP);when(f.simulations.lockOpenByPair("BTCUSDT")).thenReturn(List.of(simulation));when(f.market.historicalTrades(eq("BTCUSDT"),eq(Instant.EPOCH),eq(Instant.EPOCH.plusSeconds(30)))).thenReturn(List.of(new BinanceMarketDataClient.AggregateTrade(1,new BigDecimal("99.4"),Instant.EPOCH.plusSeconds(10)),new BinanceMarketDataClient.AggregateTrade(2,new BigDecimal("100.5"),Instant.EPOCH.plusSeconds(20))));when(f.telegram.edit(eq(42L),anyString())).thenReturn(new TelegramNotificationService.DeliveryResult(TelegramNotificationService.DeliveryResult.Status.SENT,42L,null));f.service.recover("BTCUSDT",Instant.EPOCH.plusSeconds(30));assertThat(simulation.getStatus()).isEqualTo(MixTradeSimulation.Status.STOP_LOSS_HIT);assertThat(simulation.getClosedAt()).isEqualTo(Instant.EPOCH.plusSeconds(10));verify(f.telegram).edit(eq(42L),contains("STOP LOSS HIT"));}
 static class Fixture{final Coin coin=new Coin("BTC","BTCUSDT");final BestMethodMixRepository mixes=mock(BestMethodMixRepository.class);final MixTradeSimulationRepository simulations=mock(MixTradeSimulationRepository.class);final AppSettingsRepository settings=mock(AppSettingsRepository.class);final TelegramNotificationService telegram=mock(TelegramNotificationService.class);final BinanceMarketDataClient market=mock(BinanceMarketDataClient.class);final BestMethodMix mix;final MixTradeSimulationService service;Fixture(){ReflectionTestUtils.setField(coin,"id",1L);mix=new BestMethodMix(coin,900,3,1,List.of("A","B","C"),List.of(1,1,1),List.of("A","B","C"),50,30,35,.5);ReflectionTestUtils.setField(mix,"id",2L);when(mixes.findByCoinIdAndHorizonSecondsAndSignalVersionOrderByMixSizeAscRankAsc(1,900,3)).thenReturn(List.of(mix));AppSettings config=new AppSettings(900,900);config.updateTelegram(true);when(settings.findById(1)).thenReturn(Optional.of(config));service=new MixTradeSimulationService(mixes,simulations,settings,telegram,new TelegramMessageFormatter(),market);}MixTradeSimulation simulation(Direction direction){MixTradeSimulation simulation=new MixTradeSimulation(coin,mix,direction,2,new BigDecimal("100"),new BigDecimal("0.5"),Instant.EPOCH);ReflectionTestUtils.setField(simulation,"id",99L);simulation.telegramMessage(42L);return simulation;}List<Prediction>predictions(){return List.of(prediction("A",Direction.UP),prediction("B",Direction.UP),prediction("C",Direction.DOWN));}Prediction prediction(String code,Direction direction){return new Prediction(null,coin,code,1,code,Instant.EPOCH,new BigDecimal("100"),Instant.EPOCH,new BigDecimal("100"),direction,Duration.ofMinutes(15),"5m");}}
}
